<div class="modal" x-show="cuentaActual && !cobro && !devolucion" role="dialog" aria-modal="true" aria-label="Cuenta de mesa"><div class="card dialog operation-dialog"><h2 x-text="'Cuenta de mesa '+cuentaActual?.mesa"></h2><p x-text="'Total: '+money(cuentaActual?.total)+' · Pagado: '+money(cuentaActual?.pagado)+' · Pendiente: '+money(cuentaActual?.pendiente)"></p><div class="card" x-show="cuentaActual?.abierta && Number(cuentaActual?.pendiente)>0 && (tab !== 'mesas' || mesasResumen.some(m => m.id === cuentaActual.id && m.estado === 'pendiente'))">
    <h3>Pago pendiente</h3>
    <strong x-text="money(cuentaActual?.pendiente)"></strong>
    <div class="actions">
        <button type="button" class="primary" x-show="user?.permisos.caja && caja" @click="cobrarCuenta()" :disabled="busy">Registrar pago</button>
        <button type="button" x-show="user?.permisos.caja && !caja" @click="cuentaActual=null;ir('caja')" :disabled="busy">Ir a Mi caja</button>
    </div>
    <p class="muted" x-show="user?.permisos.caja && !caja">Abre tu turno de caja para registrar el pago.</p>
    <p class="muted" x-show="!user?.permisos.caja">Pide a caja que registre el pago. Si debes cobrar, el administrador puede habilitarte el permiso de caja.</p>
</div>
<template x-for="p in cuentaActual?.pedidos||[]" :key="p.id"><div class="operation-order"><strong x-text="'#'+p.id+' · '+nombreEstado(p.estado)"></strong><template x-for="d in p.detalles" :key="d.id"><p x-text="d.cantidad+' × '+d.nombre_producto+' · '+money(d.subtotal)"></p></template><span x-text="'Saldo: '+money(p.saldo_pendiente)"></span><button @click="comprobante=p" :disabled="busy">Ver cuenta de este pedido</button><button x-show="tab !== 'mesas' && user?.permisos.caja && Number(p.saldo_pendiente)>0" @click="prepararCobro(p)" :disabled="busy||!caja">Cobrar este pedido</button><button x-show="user?.permisos.devoluciones && Number(p.pagado)>Number(p.devuelto) && p.estado!=='cancelado'" @click="prepararDevolucion(p)" :disabled="busy||!caja">Devolver / anular</button></div></template><div class="row" x-show="cuentaActual?.ultima_pagina>1"><button @click="verCuenta(cuentaActual.id,cuentaActual.pagina-1)" :disabled="busy||cuentaActual?.pagina<=1">Anterior</button><span x-text="cuentaActual?.pagina+' / '+cuentaActual?.ultima_pagina"></span><button @click="verCuenta(cuentaActual.id,cuentaActual.pagina+1)" :disabled="busy||cuentaActual?.pagina>=cuentaActual?.ultima_pagina">Siguiente</button></div><div class="actions"><button @click="agregarConsumo()" :disabled="busy||!cuentaActual?.abierta">Añadir consumos</button><details><summary>Impresión</summary><button type="button" @click="imprimirCuenta()" :disabled="busy">Imprimir resumen de consumo</button></details><button @click="cerrarCuenta()" :disabled="busy||!cuentaActual?.abierta">Liberar mesa</button><button @click="cuentaActual=null" :disabled="busy">Volver</button></div><p class="alert" x-show="error" x-text="error"></p></div></div>
<template x-if="cancelacion"><div class="modal" role="dialog" aria-modal="true" aria-label="Cancelar pedido"><form class="card dialog" @submit.prevent="cancelarPedido()"><h2>Cancelar pedido</h2><p class="muted">Un plato preparado se registra como merma. La cancelación conserva el historial.</p><label>Motivo<textarea x-model="cancelacion.motivo" minlength="5" maxlength="500" required></textarea></label><label><input type="checkbox" x-model="cancelacion.reponer_stock">Devolver existencias al inventario (solo productos recuperables)</label><p class="alert" x-show="error" x-text="error"></p><button class="primary" :disabled="busy">Confirmar cancelación</button><button type="button" @click="cancelacion=null" :disabled="busy">Volver</button></form></div></template>
<template x-if="devolucion"><div class="modal" role="dialog" aria-modal="true" aria-label="Devolución"><form class="card dialog" @submit.prevent="devolver()"><h2>Registrar devolución</h2><p class="muted">Devuelve el dinero por el medio indicado y registra después la operación. No ejecuta transferencias bancarias.</p><label>Monto<input type="number" min=".01" step=".01" x-model="devolucion.monto" required></label><label>Medio<select x-model="devolucion.medio_pago"><option value="efectivo">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="tarjeta">Tarjeta</option></select></label><label>Motivo<textarea x-model="devolucion.motivo" minlength="5" maxlength="500" required></textarea></label><label><input type="checkbox" x-model="devolucion.anular">Anular la venta completa (requiere devolver todo lo cobrado)</label><label><input type="checkbox" x-model="devolucion.reponer_stock">Reponer productos recuperables al stock</label><p class="alert" x-show="error" x-text="error"></p><button class="primary" :disabled="busy||!caja">Confirmar devolución</button><button type="button" @click="devolucion=null" :disabled="busy">Volver</button></form></div></template>
<div class="modal" x-show="recetaActual" role="dialog" aria-modal="true" aria-label="Receta y presentación"><form class="card dialog operation-dialog" @submit.prevent="guardarReceta()"><h2 x-text="'Receta / presentación: '+recetaActual?.nombre"></h2><p class="muted">Cantidad de unidades base que consume cada venta. Ejemplo: una caja consume 12 botellas. No se admiten recetas anidadas. Vaciar la receta vuelve al stock propio.</p><div class="row"><input aria-label="Buscar insumo" x-model="recetaBusqueda"><button type="button" @click="recetaPagina=1;buscarInsumos()" :disabled="busy">Buscar insumos</button></div><template x-for="p in recetaOpciones" :key="p.id"><div class="row"><span x-text="p.nombre+' · '+p.unidad"></span><button type="button" @click="if(!recetaItems.some(r=>r.insumo_id===p.id))recetaItems.push({insumo_id:p.id,cantidad:1,nombre:p.nombre})">Añadir</button></div></template><div class="row"><button type="button" :disabled="busy||recetaPagina<=1" @click="recetaPagina--;buscarInsumos()">Anterior</button><button type="button" :disabled="busy||recetaPagina>=recetaUltima" @click="recetaPagina++;buscarInsumos()">Siguiente</button></div><template x-for="(r,i) in recetaItems" :key="r.insumo_id"><div class="row"><span x-text="r.nombre"></span><input aria-label="Unidades por venta" type="number" min="1" max="10000" step="1" x-model="r.cantidad" required><button type="button" @click="recetaItems.splice(i,1)">Quitar</button></div></template><p class="alert" x-show="error" x-text="error"></p><button class="primary" :disabled="busy">Guardar composición</button><button type="button" :disabled="busy" @click="recetaActual=null">Volver</button></form></div>
